new=r'''def collect_registers(container: ET.Element, device_width: int, base_offset: int = 0, prefix: str = "") -> list[Register]:
    regs: list[Register] = []
    by_name: dict[str, Register] = {}
    for e in list(container):
        tag = local(e.tag)
        if tag == "register":
            der = e.attrib.get("derivedFrom")
            if der:
                key = der.split(".")[-1]
                key_full = prefix + key
                base = by_name.get(key_full) or by_name.get(key)
                if base is not None:
                    r = copy.deepcopy(base)
                    if ctext(e, "name", ""):
                        r.name = prefix + ctext(e, "name")
                    if ctext(e, "description", ""):
                        r.desc = ctext(e, "description")
                    if ctext(e, "addressOffset", ""):
                        r.offset = base_offset + parse_int(ctext(e, "addressOffset"), 0)
                    if ctext(e, "size", ""):
                        r.size = parse_int(ctext(e, "size"), device_width)
                    if ctext(e, "access", ""):
                        r.access = ctext(e, "access")
                    if ctext(e, "resetValue", ""):
                        r.reset_value = parse_int(ctext(e, "resetValue"), 0)
                    fields_elem = child(e, "fields")
                    if fields_elem is not None:
                        r.fields = [parse_field_xml(fe) for fe in children(fields_elem, "field")]
                    dim = ctext(e, "dim", "")
                    if dim:
                        r.dim = parse_int(dim, 1)
                        r.dim_increment = parse_int(ctext(e, "dimIncrement", "0"), 0)
                        r.dim_indices = parse_dim_indices(ctext(e, "dimIndex", ""), r.dim)
                else:
                    r = parse_register_xml(e, device_width, base_offset, prefix)
            else:
                r = parse_register_xml(e, device_width, base_offset, prefix)
            regs.append(r)
            by_name[r.name] = r
            by_name[base_name(r.name)] = r
        elif tag == "cluster":
            cname = ctext(e, "name", "")
            coff = base_offset + parse_int(ctext(e, "addressOffset", "0"), 0)
            cpref = prefix + (cname.replace("%s", "") + "_" if cname else "")
            for r in collect_registers(e, device_width, coff, cpref):
                regs.append(r); by_name[r.name] = r; by_name[base_name(r.name)] = r
    return regs
'''
s=s[:start]+new+s[end:]
p.write_text(s)
